# ================================================================
# AI-Polyglot: Agent-to-Agent Protocol Engine
# 5명 AI 에이전트의 규격화된 메시지 통신 시스템
# ================================================================

# ================================================================
# Part 1: 메시지 정의
# ================================================================

# 에이전트 ID 정의
fn getAgentId(agentName: string): string {
  if agentName == "cmo" { return "agent:cmo:opus" }
  else if agentName == "content-writer" { return "agent:content-writer:sonnet" }
  else if agentName == "social-media" { return "agent:social-media:haiku" }
  else if agentName == "community-manager" { return "agent:community-manager:haiku" }
  else if agentName == "analytics" { return "agent:analytics:haiku" }
  else { return "agent:unknown" }
}

# 메시지 생성
fn createMessage(
  fromAgent: string,
  toAgent: string,
  messageType: string,
  action: string,
  payload: map
): map {
  let timestamp = getCurrentTimestamp()
  let messageId = generateMessageId()

  return {
    "id": messageId,
    "from": getAgentId(fromAgent),
    "to": if toAgent == "broadcast" then "broadcast" else getAgentId(toAgent),
    "type": messageType,
    "action": action,
    "payload": payload,
    "timestamp": timestamp,
    "status": "pending",
    "retries": 0,
    "signature": ""
  }
}

# Request 메시지 (에이전트가 다른 에이전트에게 작업 요청)
fn createRequestMessage(
  from: string,
  to: string,
  action: string,
  payload: map

