# ================================================================
# Stage 2-1: Agent Status Panel - 테스트 스위트
# ================================================================

# ================================================================
# Part 1: Agent Status 생성 테스트
# ================================================================

fn testCreateAgentStatus(): bool {
  let agent = createAgentStatus(
    "agent:cmo:opus",
    "CMO",
    "claude-opus-4-6",
    "전략 수립",
    "주간 전략 수립",
    "running",
    1742130000,
    1742389200,
    12,
    94,
    "cmo-memory.md"
  )

  assert(agent["id"] == "agent:cmo:opus", "id 검증")
  assert(agent["name"] == "CMO", "name 검증")
  assert(agent["model"] == "claude-opus-4-6", "model 검증")
  assert(agent["taskStatus"] == "running", "taskStatus 검증")
  assert(agent["todayActions"] == 12, "todayActions 검증")
  assert(agent["successRate"] == 94, "successRate 검증")
  return true
}

fn testGetStatusIcon(): bool {
  assert(getStatusIcon("running") == "🟢", "running 아이콘")
  assert(getStatusIcon("waiting") == "🟡", "waiting 아이콘")
  assert(getStatusIcon("error") == "🔴", "error 아이콘")
  assert(getStatusIcon("idle") == "⚪", "idle 아이콘")
  return true
}

fn testGetStatusColor(): bool {
  assert(getStatusColor("running") == "#22c55e", "running 색상")
  assert(getStatusColor("waiting") == "#eab308", "waiting 색상")
  assert(getStatusColor("error") == "#ef4444", "error 색상")
  assert(getStatusColor("idle") == "#94a3b8", "idle 색상")
  return true
}

fn testStatusIconAssignment(): bool {
  let agent = createAgentStatus(
    "test", "Test", "model", "role", "task",
    "error", 0, 0, 0, 0, "mem.md"
  )
  assert(agent["statusIcon"] == "🔴", "error 상태 아이콘")
  assert(agent["statusColor"] == "#ef4444", "error 상태 색상")
  return true
}

# ================================================================
# Part 2: 팀 상태 집계 테스트
# ================================================================

fn testBuildTeamStatusPanel(): bool {
  let agents = buildSampleAgents()
  let panel = buildTeamStatusPanel(agents)

  assert(panel["totalAgents"] == 5, "팀 전체 5명")
  assert(panel["runningCount"] == 2, "실행중 2명 (ContentWriter + Analytics)")
  assert(panel["errorCount"] == 0, "에러 0명")
  return true
}

fn testTeamOnlineCount(): bool {
  let agents = buildSampleAgents()
  let panel = buildTeamStatusPanel(agents)
  # 마지막 실행이 2시간 이내인 에이전트
  assert(panel["onlineCount"] >= 0, "온라인 카운트 음수 아님")
  assert(panel["onlineCount"] <= 5, "온라인 카운트 5 이하")
  return true
}

fn testTeamSuccessRate(): bool {
  let agents = buildSampleAgents()
  let panel = buildTeamStatusPanel(agents)
  # 94 + 88 + 96 + 82 + 91 = 451 / 5 = 90
  assert(panel["teamSuccessRate"] == 90, "팀 평균 성공률 90%")
  return true
}

fn testTeamHealth(): bool {
  assert(getTeamHealth(0, 5, 5) == "healthy", "에러 없고 모두 온라인")
  assert(getTeamHealth(1, 5, 5) == "degraded", "에러 있으면 degraded")
  assert(getTeamHealth(0, 3, 5) == "partial", "일부만 온라인")
  assert(getTeamHealth(0, 0, 5) == "offline", "모두 오프라인")
  return true
}

fn testTotalActionsToday(): bool {
  let agents = buildSampleAgents()
  let panel = buildTeamStatusPanel(agents)
  # 12 + 8 + 23 + 5 + 31 = 79
  assert(panel["totalActionsToday"] == 79, "오늘 총 활동 79건")
  return true
}

# ================================================================
# Part 3: JSON 렌더러 테스트
# ================================================================

fn testSerializeAgentStatus(): bool {
  let agent = createAgentStatus(
    "agent:cmo:opus", "CMO", "claude-opus-4-6",
    "전략 수립", "주간 전략", "idle",
    1742130000, 1742389200, 5, 90, "cmo-memory.md"
  )
  let json = serializeAgentStatus(agent)

  assert(contains(json, "\"id\":\"agent:cmo:opus\""), "id 직렬화")
  assert(contains(json, "\"name\":\"CMO\""), "name 직렬화")
  assert(contains(json, "\"taskStatus\":\"idle\""), "status 직렬화")
  assert(contains(json, "\"todayActions\":5"), "actions 직렬화")
  assert(contains(json, "\"successRate\":90"), "successRate 직렬화")
  return true
}

fn testSerializeTeamPanel(): bool {
  let agents = buildSampleAgents()
  let panel = buildTeamStatusPanel(agents)
  let json = serializeTeamPanel(panel)

  assert(contains(json, "\"totalAgents\":5"), "totalAgents 직렬화")
  assert(contains(json, "\"teamSuccessRate\":90"), "successRate 직렬화")
  assert(contains(json, "\"teamHealth\":\"healthy\""), "health 직렬화")
  return true
}

fn testBuildDashboardJson(): bool {
  let agents = buildSampleAgents()
  let panel = buildTeamStatusPanel(agents)
  let json = buildDashboardJson(panel, agents)

  assert(contains(json, "\"panel\":"), "panel 키 존재")
  assert(contains(json, "\"agents\":"), "agents 키 존재")
  assert(contains(json, "\"version\":\"stage-2-1\""), "version 존재")
  assert(contains(json, "agent:cmo:opus"), "CMO 에이전트 포함")
  assert(contains(json, "agent:analytics:haiku"), "Analytics 에이전트 포함")
  return true
}

fn testJsonHasFiveAgents(): bool {
  let agents = buildSampleAgents()
  let panel = buildTeamStatusPanel(agents)
  let json = buildDashboardJson(panel, agents)

  # 5명 에이전트 모두 JSON에 포함 확인
  assert(contains(json, "agent:cmo:opus"), "CMO 포함")
  assert(contains(json, "agent:content-writer:sonnet"), "ContentWriter 포함")
  assert(contains(json, "agent:social-media:haiku"), "SocialMedia 포함")
  assert(contains(json, "agent:community-manager:haiku"), "Community 포함")
  assert(contains(json, "agent:analytics:haiku"), "Analytics 포함")
  return true
}

# ================================================================
# Part 4: HTML 렌더러 테스트
# ================================================================

fn testRenderAgentCard(): bool {
  let agent = createAgentStatus(
    "agent:cmo:opus", "CMO", "claude-opus-4-6",
    "전략 수립", "주간 전략", "running",
    1742130000, 1742389200, 12, 94, "cmo-memory.md"
  )
  let html = renderAgentCard(agent)

  assert(contains(html, "class=\"agent-card\""), "카드 클래스")
  assert(contains(html, "CMO"), "에이전트 이름")
  assert(contains(html, "claude-opus-4-6"), "모델명")
  assert(contains(html, "running"), "상태")
  assert(contains(html, "12건"), "활동 수")
  assert(contains(html, "94%"), "성공률")
  return true
}

fn testRenderTeamHeader(): bool {
  let agents = buildSampleAgents()
  let panel = buildTeamStatusPanel(agents)
  let html = renderTeamHeader(panel)

  assert(contains(html, "FreeLang AI Marketing Team"), "팀 제목")
  assert(contains(html, "healthy"), "건강 상태")
  assert(contains(html, "5"), "총 에이전트 수")
  assert(contains(html, "79"), "오늘 활동")
  assert(contains(html, "90%"), "성공률")
  return true
}

fn testRenderFullDashboard(): bool {
  let agents = buildSampleAgents()
  let panel = buildTeamStatusPanel(agents)
  let html = renderFullDashboard(panel, agents)

  assert(contains(html, "<!DOCTYPE html>"), "HTML doctype")
  assert(contains(html, "FreeLang Agent Dashboard"), "페이지 제목")
  assert(contains(html, "agents-grid"), "에이전트 그리드")
  assert(contains(html, "CMO"), "CMO 카드")
  assert(contains(html, "Analytics"), "Analytics 카드")
  assert(contains(html, "setTimeout"), "자동 새로고침 스크립트")
  return true
}

fn testDashboardCSS(): bool {
  let css = getDashboardCSS()
  assert(contains(css, "background:#0f172a"), "다크 배경색")
  assert(contains(css, "agent-card"), "카드 스타일")
  assert(contains(css, "progress-bar"), "프로그레스바")
  assert(contains(css, "stats-row"), "통계 행")
  return true
}

# ================================================================
# Part 5: 엔트리포인트 테스트
# ================================================================

fn testRunAgentStatusPanelJson(): bool {
  let result = runAgentStatusPanel("json")
  assert(contains(result, "\"panel\":"), "JSON 패널")
  assert(contains(result, "\"agents\":"), "JSON 에이전트")
  assert(len(result) > 500, "충분한 JSON 크기")
  return true
}

fn testRunAgentStatusPanelHtml(): bool {
  let result = runAgentStatusPanel("html")
  assert(contains(result, "<!DOCTYPE html>"), "HTML 문서")
  assert(contains(result, "agent-card"), "에이전트 카드")
  assert(len(result) > 1000, "충분한 HTML 크기")
  return true
}

fn testRunAgentStatusPanelUnknown(): bool {
  let result = runAgentStatusPanel("xml")
  assert(contains(result, "error"), "알 수 없는 포맷 에러")
  return true
}

fn testSampleAgentsCount(): bool {
  let agents = buildSampleAgents()
  assert(len(agents) == 5, "샘플 에이전트 5명")
  return true
}

fn testSampleAgentModels(): bool {
  let agents = buildSampleAgents()
  # CMO는 opus, ContentWriter는 sonnet, 나머지 3명은 haiku
  assert(agents[0]["model"] == "claude-opus-4-6", "CMO opus 모델")
  assert(agents[1]["model"] == "claude-sonnet-4-6", "ContentWriter sonnet 모델")
  assert(agents[2]["model"] == "claude-haiku-4-5", "SocialMedia haiku 모델")
  assert(agents[3]["model"] == "claude-haiku-4-5", "Community haiku 모델")
  assert(agents[4]["model"] == "claude-haiku-4-5", "Analytics haiku 모델")
  return true
}

# ================================================================
# 테스트 실행
# ================================================================

fn runAllTests(): bool {
  let passed = 0
  let failed = 0

  print("=== Stage 2-1: Agent Status Panel 테스트 ===")
  print("")
  print("[ Part 1: Agent Status 생성 ]")

  if testCreateAgentStatus() { print("  ✅ testCreateAgentStatus"); passed = passed + 1 }
  else { print("  ❌ testCreateAgentStatus"); failed = failed + 1 }

  if testGetStatusIcon() { print("  ✅ testGetStatusIcon"); passed = passed + 1 }
  else { print("  ❌ testGetStatusIcon"); failed = failed + 1 }

  if testGetStatusColor() { print("  ✅ testGetStatusColor"); passed = passed + 1 }
  else { print("  ❌ testGetStatusColor"); failed = failed + 1 }

  if testStatusIconAssignment() { print("  ✅ testStatusIconAssignment"); passed = passed + 1 }
  else { print("  ❌ testStatusIconAssignment"); failed = failed + 1 }

  print("")
  print("[ Part 2: 팀 상태 집계 ]")

  if testBuildTeamStatusPanel() { print("  ✅ testBuildTeamStatusPanel"); passed = passed + 1 }
  else { print("  ❌ testBuildTeamStatusPanel"); failed = failed + 1 }

  if testTeamOnlineCount() { print("  ✅ testTeamOnlineCount"); passed = passed + 1 }
  else { print("  ❌ testTeamOnlineCount"); failed = failed + 1 }

  if testTeamSuccessRate() { print("  ✅ testTeamSuccessRate"); passed = passed + 1 }
  else { print("  ❌ testTeamSuccessRate"); failed = failed + 1 }

  if testTeamHealth() { print("  ✅ testTeamHealth"); passed = passed + 1 }
  else { print("  ❌ testTeamHealth"); failed = failed + 1 }

  if testTotalActionsToday() { print("  ✅ testTotalActionsToday"); passed = passed + 1 }
  else { print("  ❌ testTotalActionsToday"); failed = failed + 1 }

  print("")
  print("[ Part 3: JSON 렌더러 ]")

  if testSerializeAgentStatus() { print("  ✅ testSerializeAgentStatus"); passed = passed + 1 }
  else { print("  ❌ testSerializeAgentStatus"); failed = failed + 1 }

  if testSerializeTeamPanel() { print("  ✅ testSerializeTeamPanel"); passed = passed + 1 }
  else { print("  ❌ testSerializeTeamPanel"); failed = failed + 1 }

  if testBuildDashboardJson() { print("  ✅ testBuildDashboardJson"); passed = passed + 1 }
  else { print("  ❌ testBuildDashboardJson"); failed = failed + 1 }

  if testJsonHasFiveAgents() { print("  ✅ testJsonHasFiveAgents"); passed = passed + 1 }
  else { print("  ❌ testJsonHasFiveAgents"); failed = failed + 1 }

  print("")
  print("[ Part 4: HTML 렌더러 ]")

  if testRenderAgentCard() { print("  ✅ testRenderAgentCard"); passed = passed + 1 }
  else { print("  ❌ testRenderAgentCard"); failed = failed + 1 }

  if testRenderTeamHeader() { print("  ✅ testRenderTeamHeader"); passed = passed + 1 }
  else { print("  ❌ testRenderTeamHeader"); failed = failed + 1 }

  if testRenderFullDashboard() { print("  ✅ testRenderFullDashboard"); passed = passed + 1 }
  else { print("  ❌ testRenderFullDashboard"); failed = failed + 1 }

  if testDashboardCSS() { print("  ✅ testDashboardCSS"); passed = passed + 1 }
  else { print("  ❌ testDashboardCSS"); failed = failed + 1 }

  print("")
  print("[ Part 5: 엔트리포인트 ]")

  if testRunAgentStatusPanelJson() { print("  ✅ testRunAgentStatusPanelJson"); passed = passed + 1 }
  else { print("  ❌ testRunAgentStatusPanelJson"); failed = failed + 1 }

  if testRunAgentStatusPanelHtml() { print("  ✅ testRunAgentStatusPanelHtml"); passed = passed + 1 }
  else { print("  ❌ testRunAgentStatusPanelHtml"); failed = failed + 1 }

  if testRunAgentStatusPanelUnknown() { print("  ✅ testRunAgentStatusPanelUnknown"); passed = passed + 1 }
  else { print("  ❌ testRunAgentStatusPanelUnknown"); failed = failed + 1 }

  if testSampleAgentsCount() { print("  ✅ testSampleAgentsCount"); passed = passed + 1 }
  else { print("  ❌ testSampleAgentsCount"); failed = failed + 1 }

  if testSampleAgentModels() { print("  ✅ testSampleAgentModels"); passed = passed + 1 }
  else { print("  ❌ testSampleAgentModels"); failed = failed + 1 }

  print("")
  print("=== 결과 ===")
  print("통과: " + intToStr(passed) + "/" + intToStr(passed + failed))

  if failed == 0 {
    print("🎉 Stage 2-1: Agent Status Panel - 모든 테스트 통과!")
    return true
  } else {
    print("❌ " + intToStr(failed) + "개 실패")
    return false
  }
}

