fn testCreateChannelReport(): bool {
  let report = createChannelReport(
    "twitter", "2026-03-17",
    8, 1240, 87, 34, 52,
    "tweet-001", 145
  )

  assert(report["channel"] == "twitter", "채널명")
  assert(report["postsCount"] == 8, "게시물 수")
  assert(report["totalViews"] == 1240, "조회수")
  assert(report["totalLikes"] == 87, "좋아요")
  assert(report["topPostScore"] == 145, "최고 점수")
  return true
}

fn testEngagementRateCalculation(): bool {
  # (87 + 34) * 100 / 1240 = 9%
  let report = createChannelReport(
    "twitter", "2026-03-17",
    8, 1240, 87, 34, 52,
    "tweet-001", 145
  )
  assert(report["engagementRate"] == 9, "참여율 9%")
  return true
}

fn testAvgProofScoreCalculation(): bool {
  # views/8=155, likes/8=10, comments/8=4
  # proofScore = (155*20/100) + (10*30/100) + (4*50/100) = 31 + 3 + 2 = 36
  let report = createChannelReport(
    "twitter", "2026-03-17",
    8, 1240, 87, 34, 52,
    "tweet-001", 145
  )
  assert(report["avgProofScore"] > 0, "avgProofScore 양수")
  return true
}

fn testGetChannelIcon(): bool {
  assert(getChannelIcon("twitter") == "🐦", "Twitter 아이콘")
  assert(getChannelIcon("linkedin") == "💼", "LinkedIn 아이콘")
  assert(getChannelIcon("blog") == "📝", "Blog 아이콘")
  assert(getChannelIcon("reddit") == "🔴", "Reddit 아이콘")
  return true
}

fn testGetChannelColor(): bool {
  assert(getChannelColor("twitter") == "#1d9bf0", "Twitter 색상")
  assert(getChannelColor("linkedin") == "#0a66c2", "LinkedIn 색상")
  assert(getChannelColor("blog") == "#8b5cf6", "Blog 색상")
  assert(getChannelColor("reddit") == "#ff4500", "Reddit 색상")
  return true
}

fn testCalculateTrend(): bool {
  assert(calculateTrend(150, 100) == "up", "50% 상승 → up")
  assert(calculateTrend(80, 100) == "down", "20% 하락 → down")
  assert(calculateTrend(105, 100) == "stable", "5% 변화 → stable")
  assert(calculateTrend(100, 0) == "stable", "이전 0 → stable")
  return true
}

fn testGetTrendIcon(): bool {
  assert(getTrendIcon("up") == "↗️", "상승 아이콘")
  assert(getTrendIcon("down") == "↘️", "하락 아이콘")
  assert(getTrendIcon("stable") == "→", "안정 아이콘")
  return true
}

fn testZeroViewsEngagement(): bool {
  let report = createChannelReport(
    "blog", "2026-03-17",
    0, 0, 0, 0, 0, "", 0
  )
  assert(report["engagementRate"] == 0, "조회수 0일 때 참여율 0")
  assert(report["avgProofScore"] == 0, "게시물 0일 때 점수 0")
  return true
}

