fn testBuildPerformanceSummary(): bool {
  let reports = buildSampleChannelReports()
  let summary = buildPerformanceSummary(reports)

  # twitter(8) + linkedin(3) + blog(2) + reddit(1) = 14
  assert(summary["totalPosts"] == 14, "총 게시물 14개")
  # 1240 + 620 + 380 + 95 = 2335
  assert(summary["totalViews"] == 2335, "총 조회수 2335")
  return true
}

fn testBestChannelDetection(): bool {
  let reports = buildSampleChannelReports()
  let summary = buildPerformanceSummary(reports)
