# ================================================================
# Phase 4-3: Network Integration
# Protocol + Delta 통합으로 실제 동기화 구현
# 클라이언트-서버 간 git push/pull 시뮬레이션
# ================================================================

# ================================================================
# Part 1: 서버 상태 (원격 저장소)
# ================================================================

fn initializeRemoteRepository(): map {
  return {
    "refs": [] as [map],
    "objects": [] as [map],
    "totalSize": 0
  }
}

# 원격 저장소에 객체 저장
fn storeRemoteObject(remote: map, objectHash: string, objectData: string): map {
  let objects = remote["objects"]

  objects = append(objects, {
    "hash": objectHash,
    "data": objectData,
    "size": len(objectData)
  })

  remote["objects"] = objects
  remote["totalSize"] = remote["totalSize"] + len(objectData)

  return remote
}

# 원격 저장소에 ref 업데이트
fn updateRemoteRef(remote: map, refName: string, commitHash: string): map {
  let refs = remote["refs"]

  # 기존 ref 찾기
  let found = false
  let i = 0

  while i < len(refs) {
    if refs[i]["name"] == refName {
      refs[i]["hash"] = commitHash
      found = true
      break
    }
    i = i + 1
  }

  # 없으면 새로 생성
  if !found {
    refs = append(refs, {
      "name": refName,
      "hash": commitHash
    })
  }

  remote["refs"] = refs

