}

fn testBuildGetRequest(): bool {
  let req = buildGetRequest("/repos/search", "tok123")
  assert(req["method"] == "GET", "GET 메서드")
  assert(contains(req["url"], "/repos/search"), "엔드포인트")
  return true
}

fn testBuildPostRequest(): bool {
  let req = buildPostRequest("/issues", "tok123", "{\"title\":\"test\"}")
  assert(req["method"] == "POST", "POST 메서드")
  assert(req["body"] == "{\"title\":\"test\"}", "바디 포함")
  return true
}

fn testEndpointBuilders(): bool {
  assert(contains(getReposEndpoint("kim"), "search"), "저장소 검색 엔드포인트")
  assert(contains(getRepoEndpoint("kim", "freelang-git"), "freelang-git"), "저장소 엔드포인트")
  assert(contains(getCommitsEndpoint("kim", "test", "main"), "commits"), "커밋 엔드포인트")
  assert(contains(getBranchesEndpoint("kim", "test"), "branches"), "브랜치 엔드포인트")
  assert(contains(getIssuesEndpoint("kim", "test"), "issues"), "이슈 엔드포인트")
  return true
}

fn testParseRepoInfo(): bool {
  let repo = parseRepoInfo("freelang-git", 12, 3, 1, "FreeLang", "2026-03-17", "main")
  assert(repo["name"] == "freelang-git", "저장소명")
  assert(repo["stars"] == 12, "스타 수")
  assert(repo["forks"] == 3, "포크 수")
  assert(repo["openIssues"] == 1, "이슈 수")
  assert(repo["defaultBranch"] == "main", "기본 브랜치")
  assert(contains(repo["webUrl"], "gogs.dclub.kr"), "웹 URL")
  return true
}

fn testActivityScore(): bool {
  # (12*40) + (3*30) + (1*30) = 480+90+30=600
  let repo = parseRepoInfo("test", 12, 3, 1, "FL", "2026", "main")
  assert(repo["activityScore"] == 600, "활동 점수 계산")
  return true
}

fn testParseCommitInfo(): bool {
  let commit = parseCommitInfo("885e4f1babcd", "feat: new feature added", "kim", "2026-03-17")
  assert(commit["shortSha"] == "885e4f1b", "짧은 SHA 8자")
  assert(commit["authorName"] == "kim", "작성자")
  assert(commit["commitType"] == "feature", "feat → feature 타입")
  return true
}

fn testDetectCommitType(): bool {
  assert(detectCommitType("feat: add feature") == "feature", "feat 감지")
  assert(detectCommitType("fix: bug fixed") == "bugfix", "fix 감지")
  assert(detectCommitType("docs: update readme") == "docs", "docs 감지")
  assert(detectCommitType("test: add tests") == "test", "test 감지")
  assert(detectCommitType("refactor: clean code") == "refactor", "refactor 감지")
  assert(detectCommitType("chore: update deps") == "chore", "chore 감지")
  assert(detectCommitType("some commit message") == "other", "기타")
  return true
}

fn testLongCommitMessage(): bool {
  let longMsg = "feat: this is a very long commit message that exceeds seventy two characters in total"
  let commit = parseCommitInfo("abc123", longMsg, "kim", "2026-03-17")
  assert(len(commit["shortMessage"]) <= 75, "short message 72자+... 이하")
  assert(contains(commit["shortMessage"], "..."), "말줄임표 포함")
  return true
}

fn testParseIssueInfo(): bool {
  let issue = parseIssueInfo(1, "map 타입 추론 버그", "open", "bug,high", "2026-03-16")
  assert(issue["number"] == 1, "이슈 번호")
  assert(issue["title"] == "map 타입 추론 버그", "이슈 제목")
  assert(issue["state"] == "open", "이슈 상태")
  assert(issue["priority"] == "high", "high 레이블 → high 우선순위")
  return true
}

fn testDetectIssuePriority(): bool {
  assert(detectIssuePriority("critical,bug") == "critical", "critical 감지")
  assert(detectIssuePriority("bug,high") == "high", "high 감지")
  assert(detectIssuePriority("enhancement") == "medium", "enhancement 감지")
  assert(detectIssuePriority("question") == "low", "기타 → low")
  return true
}

fn testBuildRepoSnapshot(): bool {
  let repo = parseRepoInfo("test-repo", 5, 1, 2, "FL", "2026-03-17", "main")
  let commits = [] as [map]
  commits = append(commits, parseCommitInfo("abc123", "feat: test", "kim", "2026-03-17"))
  let issues = [] as [map]
  issues = append(issues, parseIssueInfo(1, "test issue", "open", "bug", "2026-03-16"))

  let snap = buildRepoSnapshot(repo, commits, issues, 2)

  assert(snap["repo"]["name"] == "test-repo", "저장소명")
  assert(snap["branchCount"] == 2, "브랜치 수")
  assert(len(snap["recentCommits"]) == 1, "커밋 1개")
  assert(len(snap["openIssues"]) == 1, "이슈 1개")
  assert(snap["snapshotAt"] > 0, "스냅샷 시간")
  return true
}

fn testAssessRepoHealth(): bool {
  let repo = parseRepoInfo("test", 5, 1, 2, "FL", "2026", "main")
  let commits = [] as [map]
  commits = append(commits, parseCommitInfo("abc", "feat", "kim", "2026"))

  assert(assessRepoHealth(repo, commits, [] as [map]) == "excellent", "커밋+스타 → excellent")

  let noCommitRepo = parseRepoInfo("empty", 0, 0, 0, "FL", "2026", "main")
  assert(assessRepoHealth(noCommitRepo, [] as [map], [] as [map]) == "needs-attention", "커밋 없음 → needs-attention")
  return true
}

fn testAssessContentReadiness(): bool {
  let repo = parseRepoInfo("test", 1, 0, 0, "FL", "2026", "main")
  let commits = [] as [map]
  let i = 0
  while i < 5 {
    commits = append(commits, parseCommitInfo("abc" + intToStr(i), "feat", "kim", "2026"))
    i = i + 1
  }
  assert(assessContentReadiness(repo, commits) == "ready", "5커밋+스타 → ready")

  let smallCommits = [] as [map]
  smallCommits = append(smallCommits, parseCommitInfo("a", "feat", "kim", "2026"))
  smallCommits = append(smallCommits, parseCommitInfo("b", "fix", "kim", "2026"))
  assert(assessContentReadiness(repo, smallCommits) == "partial", "2커밋 → partial")

  assert(assessContentReadiness(repo, [] as [map]) == "not-ready", "0커밋 → not-ready")
  return true
}

fn testCalculateMarketingPriority(): bool {
  let repo = parseRepoInfo("test", 5, 2, 0, "FL", "2026", "main")
  let commits = [] as [map]
  let i = 0
  while i < 5 {
    commits = append(commits, parseCommitInfo("abc" + intToStr(i), "feat", "kim", "2026"))
    i = i + 1
  }
  let snap = buildRepoSnapshot(repo, commits, [] as [map], 1)
  let priority = calculateMarketingPriority(repo, snap)
  assert(priority > 0, "우선순위 점수 양수")
  return true
}

fn testSortByPriority(): bool {
  let items = [] as [map]
  items = append(items, {"repoName": "c", "priorityScore": 100, "health": "good", "contentReadiness": "ready", "stars": 5, "activityScore": 100})
  items = append(items, {"repoName": "a", "priorityScore": 300, "health": "excellent", "contentReadiness": "ready", "stars": 15, "activityScore": 300})
  items = append(items, {"repoName": "b", "priorityScore": 200, "health": "good", "contentReadiness": "partial", "stars": 8, "activityScore": 200})

  let sorted = sortByPriority(items)
  assert(sorted[0]["repoName"] == "a", "첫 번째: 최고 점수")
  assert(sorted[1]["repoName"] == "b", "두 번째: 중간 점수")
  assert(sorted[2]["repoName"] == "c", "세 번째: 최저 점수")
  return true
}

fn testSerializeRepoInfo(): bool {
  let repo = parseRepoInfo("freelang-git", 12, 3, 1, "FreeLang", "2026-03-17", "main")
  let json = serializeRepoInfo(repo)
