# ================================================================
# Stage 3-2: HTTP Server (대시보드 웹 서빙)
# FreeLang AI Dashboard를 HTTP로 서빙하는 서버 엔진
# ================================================================

# ================================================================
# Part 1: HTTP 기본 구조
# ================================================================

# HTTP 응답 생성
fn createHttpResponse(statusCode: i32, contentType: string, body: string): map {
  let statusText = getStatusText(statusCode)
  return {
    "statusCode": statusCode,
    "statusText": statusText,
    "contentType": contentType,
    "body": body,
    "headers": buildResponseHeaders(statusCode, contentType, len(body)),
    "size": len(body)
  }
}

# 상태 코드 텍스트
fn getStatusText(code: i32): string {
  if code == 200 { return "OK" }
  else if code == 201 { return "Created" }
  else if code == 301 { return "Moved Permanently" }
  else if code == 400 { return "Bad Request" }
  else if code == 404 { return "Not Found" }
  else if code == 405 { return "Method Not Allowed" }
  else if code == 500 { return "Internal Server Error" }
  else { return "Unknown" }
}

# 응답 헤더 생성
fn buildResponseHeaders(statusCode: i32, contentType: string, bodySize: i32): map {
  return {
    "Content-Type": contentType,
    "Content-Length": intToStr(bodySize),
    "X-Powered-By": "FreeLang/1.0",
    "Access-Control-Allow-Origin": "*",
    "Cache-Control": if statusCode == 200 then "max-age=30" else "no-store"
  }
}

# HTTP 원시 응답 문자열 (실제 전송용)
fn serializeHttpResponse(resp: map): string {
  let statusLine = "HTTP/1.1 " + intToStr(resp["statusCode"]) + " " + resp["statusText"] + "\r\n"
  let headers = resp["headers"]
  let headerLines =
    "Content-Type: " + headers["Content-Type"] + "\r\n" +
    "Content-Length: " + headers["Content-Length"] + "\r\n" +
    "X-Powered-By: " + headers["X-Powered-By"] + "\r\n" +
    "Access-Control-Allow-Origin: " + headers["Access-Control-Allow-Origin"] + "\r\n" +
    "Cache-Control: " + headers["Cache-Control"] + "\r\n"

  return statusLine + headerLines + "\r\n" + resp["body"]
}

# ================================================================
# Part 2: HTTP 요청 파서
# ================================================================

# HTTP 요청 파싱
fn parseHttpRequest(rawRequest: string): map {
  let method = extractMethod(rawRequest)
  let path = extractPath(rawRequest)
  let queryString = extractQueryString(path)
  let cleanPath = stripQueryString(path)

  return {
    "method": method,
    "path": cleanPath,
    "queryString": queryString,
    "rawPath": path,
    "userAgent": extractHeader(rawRequest, "User-Agent"),
    "accept": extractHeader(rawRequest, "Accept"),
    "isValid": method != "" && cleanPath != ""
  }
}

# 메서드 추출
fn extractMethod(raw: string): string {
  if startsWith(raw, "GET ") { return "GET" }
  else if startsWith(raw, "POST ") { return "POST" }
  else if startsWith(raw, "PUT ") { return "PUT" }
  else if startsWith(raw, "DELETE ") { return "DELETE" }
  else if startsWith(raw, "OPTIONS ") { return "OPTIONS" }
  else { return "" }
}

# 경로 추출 (두 번째 토큰)
fn extractPath(raw: string): string {
  if startsWith(raw, "GET ") { return extractToken(substr(raw, 4, len(raw) - 4)) }
  else if startsWith(raw, "POST ") { return extractToken(substr(raw, 5, len(raw) - 5)) }
  else { return "/" }
}

# 첫 토큰 추출 (공백 전)
fn extractToken(s: string): string {
  let i = 0
  while i < len(s) {
    let ch = substr(s, i, 1)
    if ch == " " || ch == "\r" || ch == "\n" {
      return substr(s, 0, i)
    }
    i = i + 1
  }
  return s
}

# 쿼리스트링 추출
fn extractQueryString(path: string): string {
  let i = 0
  while i < len(path) {
    if substr(path, i, 1) == "?" {
      return substr(path, i + 1, len(path) - i - 1)
    }
    i = i + 1
  }
  return ""
}

# 쿼리스트링 제거한 경로
fn stripQueryString(path: string): string {
  let i = 0
  while i < len(path) {
    if substr(path, i, 1) == "?" {
      return substr(path, 0, i)
    }
    i = i + 1
  }
  return path
}

# 헤더 값 추출
fn extractHeader(raw: string, headerName: string): string {
  let search = headerName + ": "
  if contains(raw, search) { return "present" }
  else { return "" }
}

# ================================================================
# Part 3: 라우터
# ================================================================

# 라우트 정의
fn createRoute(method: string, path: string, handler: string): map {
  return {
    "method": method,
    "path": path,
    "handler": handler
  }
}

# 라우트 테이블 정의
fn buildRouteTable(): [map] {
  let routes = [] as [map]

  # 메인 대시보드
  routes = append(routes, createRoute("GET", "/", "home"))
  routes = append(routes, createRoute("GET", "/dashboard", "home"))

  # Stage 2 대시보드 패널
  routes = append(routes, createRoute("GET", "/agents", "agent-status-html"))
  routes = append(routes, createRoute("GET", "/approval", "approval-html"))
  routes = append(routes, createRoute("GET", "/analytics", "analytics-html"))

  # Stage 3-1 GOGS 연동
  routes = append(routes, createRoute("GET", "/repos", "gogs-html"))

  # JSON API 엔드포인트
  routes = append(routes, createRoute("GET", "/api/agents", "agent-status-json"))
  routes = append(routes, createRoute("GET", "/api/approval", "approval-json"))
  routes = append(routes, createRoute("GET", "/api/analytics", "analytics-json"))
  routes = append(routes, createRoute("GET", "/api/repos", "gogs-json"))

  # 헬스체크
  routes = append(routes, createRoute("GET", "/health", "health"))
  routes = append(routes, createRoute("GET", "/api/status", "status"))

  return routes
}

# 라우트 매칭
fn matchRoute(routes: [map], method: string, path: string): string {
  let i = 0
  while i < len(routes) {
    let route = routes[i]
    if route["method"] == method && route["path"] == path {
      return route["handler"]
    }
    i = i + 1
  }
  return "not-found"
}

# ================================================================
# Part 4: 핸들러
# ================================================================

# 헬스체크 응답
fn handleHealth(): map {
  let body = "{\"status\":\"ok\",\"service\":\"FreeLang Agent Dashboard\",\"version\":\"stage-3-2\",\"timestamp\":" + intToStr(getCurrentTimestamp()) + "}"
  return createHttpResponse(200, "application/json", body)
}

# 서버 상태 응답
fn handleStatus(): map {
  let routes = buildRouteTable()
  let body = "{" +
    "\"service\":\"FreeLang Dashboard Server\"," +
    "\"version\":\"stage-3-2\"," +
    "\"routes\":" + intToStr(len(routes)) + "," +
    "\"uptime\":0," +
    "\"endpoints\":[" +
      "\"/\",\"/agents\",\"/approval\",\"/analytics\",\"/repos\"," +
      "\"/api/agents\",\"/api/approval\",\"/api/analytics\",\"/api/repos\"," +
      "\"/health\",\"/api/status\"" +
    "]" +
  "}"
  return createHttpResponse(200, "application/json", body)
}

# 404 응답
fn handle404(path: string): map {
  let body = "{\"error\":\"Not Found\",\"path\":\"" + path + "\",\"message\":\"Route not registered\"}"
  return createHttpResponse(404, "application/json", body)
}

# 405 응답
fn handle405(method: string): map {
  let body = "{\"error\":\"Method Not Allowed\",\"method\":\"" + method + "\"}"
  return createHttpResponse(405, "application/json", body)
}

# 500 응답
fn handle500(message: string): map {
  let body = "{\"error\":\"Internal Server Error\",\"message\":\"" + message + "\"}"
  return createHttpResponse(500, "application/json", body)
}

# 홈 페이지 (네비게이션)
fn handleHome(): map {
  let html = "<!DOCTYPE html><html lang=\"ko\"><head>" +
    "<meta charset=\"UTF-8\">" +
    "<title>FreeLang Agent Dashboard</title>" +
    "<style>" +
      "body{font-family:'Segoe UI',sans-serif;background:#0f172a;color:#e2e8f0;margin:0;display:flex;flex-direction:column;min-height:100vh}" +
      "header{background:#1e293b;padding:20px 40px;border-bottom:1px solid #334155;display:flex;align-items:center;gap:16px}" +
      "h1{margin:0;font-size:1.3rem}" +
      ".version{background:#1d4ed8;color:#fff;padding:2px 10px;border-radius:10px;font-size:0.75rem}" +
      "nav{padding:30px 40px;display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:16px;max-width:900px;margin:0 auto;width:100%;box-sizing:border-box}" +
      ".nav-card{background:#1e293b;border:1px solid #334155;border-radius:12px;padding:24px;text-decoration:none;color:#e2e8f0;transition:border-color 0.2s,transform 0.2s}" +
      ".nav-card:hover{border-color:#3b82f6;transform:translateY(-2px)}" +
      ".nav-icon{font-size:2rem;margin-bottom:12px}" +
      ".nav-title{font-size:1.05rem;font-weight:600;margin-bottom:6px}" +
      ".nav-desc{font-size:0.82rem;color:#94a3b8}" +
      ".api-badge{font-size:0.7rem;background:#312e81;color:#a5b4fc;padding:2px 8px;border-radius:4px;margin-top:8px;display:inline-block}" +
    "</style>" +
    "</head><body>" +
    "<header>" +
      "<span style=\"font-size:1.5rem\">🤖</span>" +
      "<h1>FreeLang Agent Dashboard</h1>" +
      "<span class=\"version\">Stage 3</span>" +
    "</header>" +
    "<nav>" +
      "<a href=\"/agents\" class=\"nav-card\">" +
        "<div class=\"nav-icon\">👥</div>" +
        "<div class=\"nav-title\">Agent Status</div>" +
        "<div class=\"nav-desc\">5명 AI 에이전트 실시간 상태</div>" +
        "<span class=\"api-badge\">GET /api/agents</span>" +
      "</a>" +
      "<a href=\"/approval\" class=\"nav-card\">" +
        "<div class=\"nav-icon\">📋</div>" +
        "<div class=\"nav-title\">Approval Queue</div>" +
        "<div class=\"nav-desc\">Human-in-the-loop 승인 워크플로우</div>" +
        "<span class=\"api-badge\">GET /api/approval</span>" +
      "</a>" +
      "<a href=\"/analytics\" class=\"nav-card\">" +
        "<div class=\"nav-icon\">📊</div>" +
        "<div class=\"nav-title\">Analytics</div>" +
        "<div class=\"nav-desc\">채널별 마케팅 성과 대시보드</div>" +
        "<span class=\"api-badge\">GET /api/analytics</span>" +
      "</a>" +
      "<a href=\"/repos\" class=\"nav-card\">" +
        "<div class=\"nav-icon\">🔗</div>" +
        "<div class=\"nav-title\">GOGS Live</div>" +
        "<div class=\"nav-desc\">실시간 저장소 연동 현황</div>" +
        "<span class=\"api-badge\">GET /api/repos</span>" +
      "</a>" +
      "<a href=\"/health\" class=\"nav-card\">" +
        "<div class=\"nav-icon\">💚</div>" +
        "<div class=\"nav-title\">Health Check</div>" +
        "<div class=\"nav-desc\">서버 상태 확인</div>" +
        "<span class=\"api-badge\">GET /health</span>" +
      "</a>" +
    "</nav>" +
    "</body></html>"

  return createHttpResponse(200, "text/html; charset=utf-8", html)
}

# ================================================================
# Part 5: 요청 처리 파이프라인
# ================================================================

# 요청 디스패치 (라우터 → 핸들러 → 응답)
fn dispatchRequest(rawRequest: string): map {
  let req = parseHttpRequest(rawRequest)

  if !req["isValid"] {
    return handle400()
  }

  if req["method"] != "GET" {
    return handle405(req["method"])
  }

  let routes = buildRouteTable()
  let handler = matchRoute(routes, req["method"], req["path"])

  if handler == "home" {
    return handleHome()
  } else if handler == "agent-status-html" {
    return createHttpResponse(200, "text/html; charset=utf-8", runAgentStatusPanel("html"))
  } else if handler == "approval-html" {
    return createHttpResponse(200, "text/html; charset=utf-8", runApprovalDashboard("html"))
  } else if handler == "analytics-html" {
    return createHttpResponse(200, "text/html; charset=utf-8", runAnalyticsDashboard("html"))
  } else if handler == "gogs-html" {
    return createHttpResponse(200, "text/html; charset=utf-8", runGogsClient("html"))
  } else if handler == "agent-status-json" {
    return createHttpResponse(200, "application/json", runAgentStatusPanel("json"))
  } else if handler == "approval-json" {
    return createHttpResponse(200, "application/json", runApprovalDashboard("json"))
  } else if handler == "analytics-json" {
    return createHttpResponse(200, "application/json", runAnalyticsDashboard("json"))
  } else if handler == "gogs-json" {
    return createHttpResponse(200, "application/json", runGogsClient("json"))
  } else if handler == "health" {
    return handleHealth()
  } else if handler == "status" {
    return handleStatus()
  } else {
    return handle404(req["path"])
  }
}

# 400 응답
fn handle400(): map {
  let body = "{\"error\":\"Bad Request\",\"message\":\"Invalid HTTP request\"}"
  return createHttpResponse(400, "application/json", body)
}

# ================================================================
# Part 6: 서버 설정
# ================================================================

# 서버 설정 생성
fn createServerConfig(host: string, port: i32, maxConnections: i32): map {
  return {
    "host": host,
    "port": port,
    "maxConnections": maxConnections,
    "readTimeout": 30,
    "writeTimeout": 30,
    "baseUrl": "http://" + host + ":" + intToStr(port),
    "routes": buildRouteTable()
  }
}

# 서버 설정 JSON
fn serializeServerConfig(config: map): string {
  let routes = config["routes"]
  let routeCount = len(routes)
  return "{" +
    "\"host\":\"" + config["host"] + "\"," +
    "\"port\":" + intToStr(config["port"]) + "," +
    "\"maxConnections\":" + intToStr(config["maxConnections"]) + "," +
    "\"baseUrl\":\"" + config["baseUrl"] + "\"," +
    "\"routeCount\":" + intToStr(routeCount) +
  "}"
}

# 기본 서버 설정
fn getDefaultServerConfig(): map {
  return createServerConfig("0.0.0.0", 8080, 100)
}

# ================================================================
# Part 7: 엔트리포인트
# ================================================================

fn runHttpServer(operation: string): string {
  if operation == "config" {
    let config = getDefaultServerConfig()
    return serializeServerConfig(config)
  } else if operation == "health" {
    let resp = handleHealth()
    return resp["body"]
  } else if operation == "status" {
    let resp = handleStatus()
    return resp["body"]
  } else if operation == "home" {
    let resp = handleHome()
    return resp["body"]
  } else if operation == "routes" {
    let routes = buildRouteTable()
    return "총 " + intToStr(len(routes)) + "개 라우트 등록됨"
  } else {
    return "error: unknown operation. use 'config', 'health', 'status', 'home', 'routes'"
  }
}

