  routes = append(routes, createRoute("GET", "/dashboard", "home"))

  # Stage 2 대시보드 패널
  routes = append(routes, createRoute("GET", "/agents", "agent-status-html"))
  routes = append(routes, createRoute("GET", "/approval", "approval-html"))
  routes = append(routes, createRoute("GET", "/analytics", "analytics-html"))

  # Stage 3-1 GOGS 연동
  routes = append(routes, createRoute("GET", "/repos", "gogs-html"))

  # JSON API 엔드포인트
  routes = append(routes, createRoute("GET", "/api/agents", "agent-status-json"))
  routes = append(routes, createRoute("GET", "/api/approval", "approval-json"))
  routes = append(routes, createRoute("GET", "/api/analytics", "analytics-json"))
  routes = append(routes, createRoute("GET", "/api/repos", "gogs-json"))

  # 헬스체크
  routes = append(routes, createRoute("GET", "/health", "health"))
  routes = append(routes, createRoute("GET", "/api/status", "status"))

  return routes
}

# 라우트 매칭
fn matchRoute(routes: [map], method: string, path: string): string {
  let i = 0
  while i < len(routes) {
    let route = routes[i]
    if route["method"] == method && route["path"] == path {
      return route["handler"]
    }
    i = i + 1
  }
  return "not-found"
}

# ================================================================
# Part 4: 핸들러
# ================================================================

# 헬스체크 응답
fn handleHealth(): map {
  let body = "{\"status\":\"ok\",\"service\":\"FreeLang Agent Dashboard\",\"version\":\"stage-3-2\",\"timestamp\":" + intToStr(getCurrentTimestamp()) + "}"
  return createHttpResponse(200, "application/json", body)
}

# 서버 상태 응답
fn handleStatus(): map {
  let routes = buildRouteTable()
  let body = "{" +
    "\"service\":\"FreeLang Dashboard Server\"," +
    "\"version\":\"stage-3-2\"," +
    "\"routes\":" + intToStr(len(routes)) + "," +
    "\"uptime\":0," +
    "\"endpoints\":[" +
      "\"/\",\"/agents\",\"/approval\",\"/analytics\",\"/repos\"," +
      "\"/api/agents\",\"/api/approval\",\"/api/analytics\",\"/api/repos\"," +
      "\"/health\",\"/api/status\"" +
    "]" +
  "}"
  return createHttpResponse(200, "application/json", body)
}

# 404 응답
fn handle404(path: string): map {
  let body = "{\"error\":\"Not Found\",\"path\":\"" + path + "\",\"message\":\"Route not registered\"}"
  return createHttpResponse(404, "application/json", body)
}

# 405 응답
fn handle405(method: string): map {
  let body = "{\"error\":\"Method Not Allowed\",\"method\":\"" + method + "\"}"
  return createHttpResponse(405, "application/json", body)
}

# 500 응답
fn handle500(message: string): map {
  let body = "{\"error\":\"Internal Server Error\",\"message\":\"" + message + "\"}"
  return createHttpResponse(500, "application/json", body)
}

