# ================================================================
# Stage 3-3: Live Posting Connector (소셜 채널 API 연동)
# Twitter/LinkedIn/Blog/Reddit 실제 발행 준비 커넥터
# ================================================================

# ================================================================
# Part 1: 채널 커넥터 공통 구조
# ================================================================

# 채널 커넥터 생성
fn createChannelConnector(
  channelId: string,
  channelName: string,
  apiBaseUrl: string,
  authType: string,
  rateLimit: i32,
  maxPostLength: i32
): map {
  return {
    "id": channelId,
    "name": channelName,
    "apiBaseUrl": apiBaseUrl,
    "authType": authType,
    "rateLimit": rateLimit,      # 시간당 최대 요청 수
    "maxPostLength": maxPostLength,
    "isConnected": false,
    "lastPostAt": 0,
    "postsToday": 0,
    "errorCount": 0,
    "status": "ready"            # "ready" | "connected" | "rate-limited" | "error"
  }
}

# 커넥터 상태 확인
fn checkConnectorStatus(connector: map): string {
  if connector["errorCount"] > 3 { return "error" }
  else if connector["isConnected"] == false { return "ready" }
  else if isRateLimited(connector) { return "rate-limited" }
  else { return "connected" }
}

# 레이트 리밋 확인 (시간당 제한)
fn isRateLimited(connector: map): bool {
  let now = getCurrentTimestamp()
  let oneHour = 3600
  let windowStart = now - oneHour
  # 간단화: postsToday가 rateLimit 초과면 제한
  return connector["postsToday"] >= connector["rateLimit"]
}

# ================================================================
# Part 2: 포스트 페이로드 빌더
# ================================================================

# 발행 페이로드 생성
fn createPostPayload(
  channel: string,
  contentType: string,   # "blog" | "thread" | "article" | "comment"
  title: string,
  body: string,
  tags: [string],
  mediaUrls: [string],
  scheduledAt: i64
): map {
  let validationResult = validatePayload(channel, body)

  return {
    "id": "post-" + channel + "-" + intToStr(getCurrentTimestamp()),
    "channel": channel,
    "contentType": contentType,
    "title": title,
    "body": body,
    "bodyLength": len(body),
    "tags": tags,
    "mediaUrls": mediaUrls,
    "scheduledAt": scheduledAt,
    "isValid": validationResult["isValid"],
    "validationErrors": validationResult["errors"],
    "formattedBody": formatForChannel(channel, body, tags)
  }
}

# 채널별 본문 포맷
fn formatForChannel(channel: string, body: string, tags: [string]): string {
  if channel == "twitter" {
    return formatForTwitter(body, tags)
  } else if channel == "linkedin" {
    return formatForLinkedIn(body, tags)
  } else if channel == "reddit" {
    return formatForReddit(body)
  } else if channel == "blog" {
    return formatForBlog(body, tags)
  } else {
    return body
  }
}

# Twitter 포맷 (280자 제한, 해시태그)
fn formatForTwitter(body: string, tags: [string]): string {
  let hashtags = ""
  let i = 0
  while i < len(tags) {
    if i < 3 {  # 최대 3개 해시태그
      hashtags = hashtags + " #" + tags[i]
    }
    i = i + 1
  }

  let combined = body + hashtags
  if len(combined) <= 280 {
    return combined
  } else {
    # 280자 트리밍
    let available = 280 - len(hashtags) - 3
    return substr(body, 0, available) + "..." + hashtags
  }
}

# LinkedIn 포맷 (3000자, 전문적 톤)
fn formatForLinkedIn(body: string, tags: [string]): string {
  let tagLine = ""
  let i = 0
  while i < len(tags) {
    tagLine = tagLine + " #" + tags[i]
    i = i + 1
  }

  let formatted = body + "\n\n" + tagLine
  if len(formatted) <= 3000 {
    return formatted
  } else {
    return substr(body, 0, 2990) + "..." + "\n" + tagLine
  }
}

# Reddit 포맷 (마크다운)
fn formatForReddit(body: string): string {
  # Reddit은 마크다운 그대로 사용
  return body
}

# Blog 포맷 (Front Matter + 마크다운)
fn formatForBlog(body: string, tags: [string]): string {
  let tagList = "["
  let i = 0
  while i < len(tags) {
    if i > 0 { tagList = tagList + ", " }
    tagList = tagList + "\"" + tags[i] + "\""
    i = i + 1
  }
  tagList = tagList + "]"

  return "---\ntags: " + tagList + "\ndate: 2026-03-17\n---\n\n" + body
}

# ================================================================
# Part 3: 페이로드 검증
# ================================================================

# 채널별 제한 확인
fn getChannelLimit(channel: string): i32 {
  if channel == "twitter" { return 280 }
  else if channel == "linkedin" { return 3000 }
  else if channel == "reddit" { return 40000 }
  else if channel == "blog" { return 100000 }
  else { return 1000 }
}

# 페이로드 유효성 검사
fn validatePayload(channel: string, body: string): map {
  let errors = [] as [string]
  let limit = getChannelLimit(channel)

  if len(body) == 0 {
    errors = append(errors, "본문이 비어있습니다")
  }

  if len(body) > limit {
    errors = append(errors, channel + " 최대 길이 " + intToStr(limit) + "자 초과")
  }

  if channel == "twitter" && len(body) < 10 {
    errors = append(errors, "Twitter 최소 10자 이상")
  }

  return {
    "isValid": len(errors) == 0,
    "errors": errors,
    "bodyLength": len(body),
    "limit": limit
  }
}

# ================================================================
# Part 4: 발행 큐
# ================================================================

# 발행 큐 아이템 생성
fn createQueueItem(payload: map, connector: map, priority: i32): map {
  return {
    "id": "queue-" + payload["id"],
    "payload": payload,
    "channel": payload["channel"],
    "status": "queued",          # "queued" | "sending" | "sent" | "failed" | "cancelled"
    "priority": priority,         # 1(높음) ~ 5(낮음)
    "attempts": 0,
    "maxAttempts": 3,
    "queuedAt": getCurrentTimestamp(),
    "sentAt": 0,
    "errorMessage": "",
    "estimatedDelay": calculateDelay(connector)
  }
}

# 지연 시간 계산 (분 단위)
fn calculateDelay(connector: map): i32 {
  if connector["id"] == "twitter" { return 0 }
  else if connector["id"] == "linkedin" { return 50 }
  else if connector["id"] == "blog" { return 30 }
  else if connector["id"] == "reddit" { return 60 }
  else { return 0 }
}

# 큐 통계
fn buildQueueStats(items: [map]): map {
  let queued = 0
  let sent = 0
  let failed = 0
  let i = 0

  while i < len(items) {
    let status = items[i]["status"]
    if status == "queued" { queued = queued + 1 }
    else if status == "sent" { sent = sent + 1 }
    else if status == "failed" { failed = failed + 1 }
    i = i + 1
  }

  return {
    "total": len(items),
    "queued": queued,
    "sent": sent,
    "failed": failed,
    "successRate": if (sent + failed) > 0 then (sent * 100) / (sent + failed) else 0
  }
}

# ================================================================
# Part 5: 커넥터 풀
# ================================================================

# 4개 채널 커넥터 초기화
fn initializeConnectorPool(): [map] {
  let pool = [] as [map]

  pool = append(pool, createChannelConnector(
    "twitter", "Twitter/X",
    "https://api.twitter.com/2",
    "OAuth2-Bearer",
    300, 280
  ))

  pool = append(pool, createChannelConnector(
    "linkedin", "LinkedIn",
    "https://api.linkedin.com/v2",
    "OAuth2-AuthCode",
    100, 3000
  ))

  pool = append(pool, createChannelConnector(
    "blog", "GOGS Blog",
    "https://gogs.dclub.kr/api/v1",
    "Token",
    500, 100000
  ))

  pool = append(pool, createChannelConnector(
    "reddit", "Reddit",
    "https://oauth.reddit.com/api",
    "OAuth2-Password",
    60, 40000
  ))

  return pool
}

# 채널 ID로 커넥터 찾기
fn findConnector(pool: [map], channelId: string): map {
  let i = 0
  while i < len(pool) {
    if pool[i]["id"] == channelId {
      return pool[i]
    }
    i = i + 1
  }
  return {
    "id": "unknown",
    "name": "Unknown",
    "status": "error",
    "isConnected": false
  }
}

# ================================================================
# Part 6: JSON 직렬화
# ================================================================

# 커넥터 JSON
fn serializeConnector(connector: map): string {
  let connectedStr = if connector["isConnected"] == true then "true" else "false"
  return "{" +
    "\"id\":\"" + connector["id"] + "\"," +
    "\"name\":\"" + connector["name"] + "\"," +
    "\"authType\":\"" + connector["authType"] + "\"," +
    "\"rateLimit\":" + intToStr(connector["rateLimit"]) + "," +
    "\"maxPostLength\":" + intToStr(connector["maxPostLength"]) + "," +
    "\"isConnected\":" + connectedStr + "," +
    "\"status\":\"" + checkConnectorStatus(connector) + "\"," +
    "\"postsToday\":" + intToStr(connector["postsToday"]) +
  "}"
}

# 페이로드 JSON
fn serializePayload(payload: map): string {
  let validStr = if payload["isValid"] == true then "true" else "false"
  return "{" +
    "\"id\":\"" + payload["id"] + "\"," +
    "\"channel\":\"" + payload["channel"] + "\"," +
    "\"contentType\":\"" + payload["contentType"] + "\"," +
    "\"title\":\"" + payload["title"] + "\"," +
    "\"bodyLength\":" + intToStr(payload["bodyLength"]) + "," +
    "\"isValid\":" + validStr + "," +
    "\"formattedBodyLength\":" + intToStr(len(payload["formattedBody"])) +
  "}"
}

# 큐 아이템 JSON
fn serializeQueueItem(item: map): string {
  return "{" +
    "\"id\":\"" + item["id"] + "\"," +
    "\"channel\":\"" + item["channel"] + "\"," +
    "\"status\":\"" + item["status"] + "\"," +
    "\"priority\":" + intToStr(item["priority"]) + "," +
    "\"attempts\":" + intToStr(item["attempts"]) + "," +
    "\"estimatedDelay\":" + intToStr(item["estimatedDelay"]) +
  "}"
}

# 전체 커넥터 풀 JSON
fn buildConnectorPoolJson(pool: [map]): string {
  let poolJson = "["
  let i = 0
  while i < len(pool) {
    if i > 0 { poolJson = poolJson + "," }
    poolJson = poolJson + serializeConnector(pool[i])
    i = i + 1
  }
  poolJson = poolJson + "]"

  return "{" +
    "\"connectors\":" + poolJson + "," +
    "\"totalChannels\":" + intToStr(len(pool)) + "," +
    "\"version\":\"stage-3-3\"" +
  "}"
}

# ================================================================
# Part 7: HTML 렌더러 (커넥터 상태 UI)
# ================================================================

# 커넥터 상태 카드 HTML
fn renderConnectorCard(connector: map): string {
  let status = checkConnectorStatus(connector)
  let statusColor = if status == "connected" then "#22c55e"
    else if status == "rate-limited" then "#f59e0b"
    else if status == "error" then "#ef4444"
    else "#94a3b8"

  let authBadge = "<span class=\"auth-badge\">" + connector["authType"] + "</span>"

  let rateLimitBar = "<div class=\"rate-bar\">" +
    "<div class=\"rate-fill\" style=\"width:" +
    intToStr(if connector["rateLimit"] > 0 then (connector["postsToday"] * 100) / connector["rateLimit"] else 0) +
    "%\"></div>" +
  "</div>"

  return "<div class=\"connector-card\" data-status=\"" + status + "\">" +
    "<div class=\"conn-header\">" +
      "<span class=\"conn-status\" style=\"background:" + statusColor + "\"></span>" +
      "<span class=\"conn-name\">" + connector["name"] + "</span>" +
      authBadge +
    "</div>" +
    "<div class=\"conn-stats\">" +
      "<div class=\"conn-stat\"><span class=\"stat-v\">" + intToStr(connector["maxPostLength"]) + "</span><span class=\"stat-l\">최대 문자</span></div>" +
      "<div class=\"conn-stat\"><span class=\"stat-v\">" + intToStr(connector["rateLimit"]) + "</span><span class=\"stat-l\">시간당 한도</span></div>" +
      "<div class=\"conn-stat\"><span class=\"stat-v\">" + intToStr(connector["postsToday"]) + "</span><span class=\"stat-l\">오늘 발행</span></div>" +
