}

# 커넥터 풀 대시보드 CSS
fn getConnectorCSS(): string {
  return "<style>" +
    ".connector-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:14px;margin-top:16px}" +
    ".connector-card{background:#1e293b;border-radius:10px;padding:16px;border:1px solid #334155}" +
    ".connector-card[data-status=connected]{border-color:#22c55e55}" +
    ".connector-card[data-status=error]{border-color:#ef444455}" +
    ".connector-card[data-status=rate-limited]{border-color:#f59e0b55}" +
    ".conn-header{display:flex;align-items:center;gap:8px;margin-bottom:14px}" +
    ".conn-status{width:10px;height:10px;border-radius:50%;flex-shrink:0}" +
