    ".auth-badge{font-size:0.7rem;background:#1e3a5f;color:#60a5fa;padding:2px 8px;border-radius:4px;font-family:monospace}" +
    ".conn-stats{display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;margin-bottom:12px}" +
    ".conn-stat{background:#0f172a;padding:8px 4px;border-radius:6px;text-align:center}" +
    ".stat-v{display:block;font-size:1rem;font-weight:700;color:#f1f5f9}" +
    ".stat-l{font-size:0.68rem;color:#64748b}" +
    ".conn-rate{margin-bottom:10px}" +
    ".rate-label{font-size:0.72rem;color:#64748b;display:block;margin-bottom:4px}" +
    ".rate-bar{background:#334155;border-radius:4px;height:5px;overflow:hidden}" +
    ".rate-fill{height:100%;background:#3b82f6;border-radius:4px}" +
    ".conn-api{font-size:0.72rem;color:#475569;font-family:monospace;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}" +
    "</style>"
}

# 발행 풀 대시보드 HTML
fn renderConnectorDashboard(pool: [map]): string {
  let cardsHtml = ""
  let i = 0
  while i < len(pool) {
    cardsHtml = cardsHtml + renderConnectorCard(pool[i])
    i = i + 1
  }

  let readyCount = 0
  let j = 0
  while j < len(pool) {
    if checkConnectorStatus(pool[j]) != "error" {
      readyCount = readyCount + 1
    }
    j = j + 1
  }

  return "<!DOCTYPE html><html lang=\"ko\"><head>" +
    "<meta charset=\"UTF-8\">" +
    "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\">" +
    "<title>Live Posting - FreeLang</title>" +
    "<style>body{font-family:'Segoe UI',sans-serif;background:#0f172a;color:#e2e8f0;margin:0;padding:20px;max-width:1000px;margin:0 auto}</style>" +
    getConnectorCSS() +
    "</head><body>" +
    "<div style=\"background:#1e293b;border-radius:12px;padding:20px;margin-bottom:20px;border:1px solid #334155\">" +
      "<h2 style=\"margin:0 0 8px 0\">📡 Live Posting Connector</h2>" +
      "<p style=\"color:#94a3b8;margin:0 0 12px 0\">소셜 채널 발행 API 연동 상태</p>" +
      "<div style=\"display:flex;gap:16px\">" +
        "<div style=\"background:#0f172a;padding:12px 20px;border-radius:8px;text-align:center\">" +
          "<div style=\"font-size:1.6rem;font-weight:700;color:#60a5fa\">" + intToStr(readyCount) + "/" + intToStr(len(pool)) + "</div>" +
          "<div style=\"font-size:0.75rem;color:#94a3b8\">준비된 채널</div>" +
        "</div>" +
      "</div>" +
    "</div>" +
    "<div class=\"connector-grid\">" + cardsHtml + "</div>" +
    "</body></html>"
}

# ================================================================
# Part 8: 샘플 데이터
# ================================================================

fn buildSampleQueueItems(): [map] {
  let pool = initializeConnectorPool()
  let items = [] as [map]

  # Twitter 스레드
  let tags1 = ["FreeLang", "ProgrammingLanguage", "OpenSource"] as [string]
  let media1 = [] as [string]
  let payload1 = createPostPayload(
    "twitter", "thread",
    "FreeLang v4 새 기능 소개",
    "FreeLang v4가 출시되었습니다! 새로운 async/await 문법으로 더 직관적인 비동기 프로그래밍이 가능해졌습니다.",
    tags1, media1, 1742133600
  )
  let tw = findConnector(pool, "twitter")
  items = append(items, createQueueItem(payload1, tw, 1))

  # LinkedIn 아티클
  let tags2 = ["FreeLang", "SystemProgramming", "Performance"] as [string]
  let media2 = [] as [string]
  let payload2 = createPostPayload(
    "linkedin", "article",
    "FreeLang의 메모리 관리 설계",
    "우리 팀은 FreeLang의 메모리 관리 시스템을 설계할 때 안전성과 성능 사이의 균형을 최우선으로 고려했습니다.",
    tags2, media2, 1742136000
  )
  let li = findConnector(pool, "linkedin")
  items = append(items, createQueueItem(payload2, li, 2))

  # Blog 포스트
  let tags3 = ["FreeLang", "Tutorial", "GettingStarted"] as [string]
  let media3 = [] as [string]
  let payload3 = createPostPayload(
    "blog", "blog",
    "FreeLang 시작하기",
    "이 가이드에서는 FreeLang 설치부터 첫 번째 프로그램 작성까지 단계별로 설명합니다.",
    tags3, media3, 1742130000
  )
  let blog = findConnector(pool, "blog")
  items = append(items, createQueueItem(payload3, blog, 1))

  return items
}

# ================================================================
# Part 9: 엔트리포인트
# ================================================================

fn runPostingConnector(outputFormat: string): string {
  let pool = initializeConnectorPool()

  if outputFormat == "json" {
    return buildConnectorPoolJson(pool)
  } else if outputFormat == "html" {
    return renderConnectorDashboard(pool)
  } else if outputFormat == "queue" {
    let items = buildSampleQueueItems()
    let stats = buildQueueStats(items)
    let statsJson = "{\"total\":" + intToStr(stats["total"]) + ",\"queued\":" + intToStr(stats["queued"]) + ",\"sent\":" + intToStr(stats["sent"]) + "}"
    return statsJson
  } else {
    return "error: unknown format. use 'json', 'html', or 'queue'"
  }
}

toolUseResult.content:
# ================================================================
# Stage 3-3: Live Posting Connector (소셜 채널 API 연동)
# Twitter/LinkedIn/Blog/Reddit 실제 발행 준비 커넥터
# ================================================================

# ================================================================
# Part 1: 채널 커넥터 공통 구조
# ================================================================

# 채널 커넥터 생성
fn createChannelConnector(
  channelId: string,
  channelName: string,
  apiBaseUrl: string,
  authType: string,
  rateLimit: i32,
  maxPostLength: i32
): map {
  return {
    "id": channelId,
    "name": channelName,
    "apiBaseUrl": apiBaseUrl,
    "authType": authType,
    "rateLimit": rateLimit,      # 시간당 최대 요청 수
    "maxPostLength": maxPostLength,
    "isConnected": false,
    "lastPostAt": 0,
    "postsToday": 0,
    "errorCount": 0,
    "status": "ready"            # "ready" | "connected" | "rate-limited" | "error"
  }
}

# 커넥터 상태 확인
fn checkConnectorStatus(connector: map): string {
  if connector["errorCount"] > 3 { return "error" }
  else if connector["isConnected"] == false { return "ready" }
  else if isRateLimited(connector) { return "rate-limited" }
  else { return "connected" }
}

# 레이트 리밋 확인 (시간당 제한)
fn isRateLimited(connector: map): bool {
  let now = getCurrentTimestamp()
  let oneHour = 3600
  let windowStart = now - oneHour
  # 간단화: postsToday가 rateLimit 초과면 제한
  return connector["postsToday"] >= connector["rateLimit"]
}

# ================================================================
# Part 2: 포스트 페이로드 빌더
# ================================================================

# 발행 페이로드 생성
fn createPostPayload(
  channel: string,
  contentType: string,   # "blog" | "thread" | "article" | "comment"
  title: string,
  body: string,
  tags: [string],
  mediaUrls: [string],
  scheduledAt: i64
): map {
  let validationResult = validatePayload(channel, body)

  return {
    "id": "post-" + channel + "-" + intToStr(getCurrentTimestamp()),
    "channel": channel,
    "contentType": contentType,
    "title": title,
    "body": body,
    "bodyLength": len(body),
    "tags": tags,
    "mediaUrls": mediaUrls,
    "scheduledAt": scheduledAt,
    "isValid": validationResult["isValid"],
    "validationErrors": validationResult["errors"],
    "formattedBody": formatForChannel(channel, body, tags)
  }
}

# 채널별 본문 포맷
fn formatForChannel(channel: string, body: string, tags: [string]): string {
  if channel == "twitter" {
    return formatForTwitter(body, tags)
  } else if channel == "linkedin" {
    return formatForLinkedIn(body, tags)
  } else if channel == "reddit" {
    return formatForReddit(body)
  } else if channel == "blog" {
    return formatForBlog(body, tags)
  } else {
    return body
  }
}

# Twitter 포맷 (280자 제한, 해시태그)
fn formatForTwitter(body: string, tags: [string]): string {
  let hashtags = ""
  let i = 0
  while i < len(tags) {
    if i < 3 {  # 최대 3개 해시태그
      hashtags = hashtags + " #" + tags[i]
    }
    i = i + 1
  }

  let combined = body + hashtags
  if len(combined) <= 280 {
    return combined
  } else {
    # 280자 트리밍
    let available = 280 - len(hashtags) - 3
    return substr(body, 0, available) + "..." + hashtags
  }
}

# LinkedIn 포맷 (3000자, 전문적 톤)
fn formatForLinkedIn(body: string, tags: [string]): string {
  let tagLine = ""
  let i = 0
  while i < len(tags) {
    tagLine = tagLine + " #" + tags[i]
    i = i + 1
  }

  let formatted = body + "\n\n" + tagLine
  if len(formatted) <= 3000 {
    return formatted
  } else {
    return substr(body, 0, 2990) + "..." + "\n" + tagLine
  }
}

# Reddit 포맷 (마크다운)
fn formatForReddit(body: string): string {
  # Reddit은 마크다운 그대로 사용
  return body
}

# Blog 포맷 (Front Matter + 마크다운)
fn formatForBlog(body: string, tags: [string]): string {
  let tagList = "["
  let i = 0
  while i < len(tags) {
    if i > 0 { tagList = tagList + ", " }
    tagList = tagList + "\"" + tags[i] + "\""
    i = i + 1
  }
  tagList = tagList + "]"

  return "---\ntags: " + tagList + "\ndate: 2026-03-17\n---\n\n" + body
}

# ================================================================
# Part 3: 페이로드 검증
# ================================================================

# 채널별 제한 확인
fn getChannelLimit(channel: string): i32 {
  if channel == "twitter" { return 280 }
  else if channel == "linkedin" { return 3000 }
  else if channel == "reddit" { return 40000 }
  else if channel == "blog" { return 100000 }
  else { return 1000 }
}

# 페이로드 유효성 검사
fn validatePayload(channel: string, body: string): map {
  let errors = [] as [string]
  let limit = getChannelLimit(channel)

  if len(body) == 0 {
    errors = append(errors, "본문이 비어있습니다")
  }

  if len(body) > limit {
    errors = append(errors, channel + " 최대 길이 " + intToStr(limit) + "자 초과")
  }

  if channel == "twitter" && len(body) < 10 {
    errors = append(errors, "Twitter 최소 10자 이상")
  }

  return {
    "isValid": len(errors) == 0,
    "errors": errors,
    "bodyLength": len(body),
    "limit": limit
  }
}

# ================================================================
# Part 4: 발행 큐
# ================================================================

# 발행 큐 아이템 생성
fn createQueueItem(payload: map, connector: map, priority: i32): map {
  return {
    "id": "queue-" + payload["id"],
    "payload": payload,
    "channel": payload["channel"],
    "status": "queued",          # "queued" | "sending" | "sent" | "failed" | "cancelled"
    "priority": priority,         # 1(높음) ~ 5(낮음)
    "attempts": 0,
    "maxAttempts": 3,
    "queuedAt": getCurrentTimestamp(),
    "sentAt": 0,
    "errorMessage": "",
    "estimatedDelay": calculateDelay(connector)
  }
}

# 지연 시간 계산 (분 단위)
fn calculateDelay(connector: map): i32 {
  if connector["id"] == "twitter" { return 0 }
  else if connector["id"] == "linkedin" { return 50 }
  else if connector["id"] == "blog" { return 30 }
  else if connector["id"] == "reddit" { return 60 }
  else { return 0 }
}

# 큐 통계
fn buildQueueStats(items: [map]): map {
  let queued = 0
  let sent = 0
  let failed = 0
  let i = 0

  while i < len(items) {
    let status = items[i]["status"]
    if status == "queued" { queued = queued + 1 }
    else if status == "sent" { sent = sent + 1 }
    else if status == "failed" { failed = failed + 1 }
    i = i + 1
  }

  return {
    "total": len(items),
    "queued": queued,
    "sent": sent,
    "failed": failed,
    "successRate": if (sent + failed) > 0 then (sent * 100) / (sent + failed) else 0
  }
}

# ================================================================
# Part 5: 커넥터 풀
# ================================================================

# 4개 채널 커넥터 초기화
fn initializeConnectorPool(): [map] {
  let pool = [] as [map]

  pool = append(pool, createChannelConnector(
    "twitter", "Twitter/X",
    "https://api.twitter.com/2",
    "OAuth2-Bearer",
    300, 280
  ))

  pool = append(pool, createChannelConnector(
