  ))

  pool = append(pool, createChannelConnector(
    "blog", "GOGS Blog",
    "https://gogs.dclub.kr/api/v1",
    "Token",
    500, 100000
  ))

  pool = append(pool, createChannelConnector(
    "reddit", "Reddit",
    "https://oauth.reddit.com/api",
    "OAuth2-Password",
    60, 40000
  ))

  return pool
}

# 채널 ID로 커넥터 찾기
fn findConnector(pool: [map], channelId: string): map {
  let i = 0
  while i < len(pool) {
    if pool[i]["id"] == channelId {
      return pool[i]
    }
    i = i + 1
  }
  return {
    "id": "unknown",
    "name": "Unknown",
    "status": "error",
    "isConnected": false
  }
}

# ================================================================
# Part 6: JSON 직렬화
