# Part 2: 커맨드 실행
# ================================================================

fn executeCommand(parsedCmd: map): i32 {
  let command = parsedCmd["command"]

  if command == "init" {
    return cmdInit(parsedCmd["path"])
  } else if command == "add" {
    return cmdAdd(parsedCmd["files"])
  } else if command == "commit" {
    return cmdCommit(parsedCmd["message"], parsedCmd["author"])
  } else if command == "log" {
    return cmdLog(parsedCmd["maxCount"])
  } else if command == "fsck" {
    return cmdFsck()
  } else if command == "cat-file" {
    return cmdCatFile(parsedCmd["hash"])
  } else if command == "status" {
    return cmdStatus()
  } else {
    return cmdHelp()
  }
}

# ================================================================
# Part 3: 각 커맨드 구현
# ================================================================

fn cmdInit(path: string): i32 {
  println("🔨 Initializing FreeGit repository...")

  let repo = initRepo(path)

  if repo["initialized"] {
    println("✅ Repository initialized at: " + path)
    return 0
  } else {
    println("❌ Failed to initialize repository")
    return 1
  }
}

fn cmdAdd(files: [string]): i32 {
  if len(files) == 0 {
    println("❌ No files specified")
    return 1
  }

  println("📝 Adding files...")

  let repo = openRepo(".")  # 현재 디렉토리의 저장소 열기

  let fileInfos = [] as [map]
  for filePath in files {
    fileInfos = append(fileInfos, { "path": filePath, "name": filePath })
  }

  let hashes = addFiles(repo, fileInfos)

  for i in range(0, len(files)) {
    let fileName = files[i]
    let hash = hashes[i]
    println("  ✓ " + fileName + " -> " + substr(hash, 0, 8))
  }

  println("✅ Added " + toString(len(files)) + " files")
  return 0
}

fn cmdCommit(message: string, author: string): i32 {
  if message == "" {
    println("❌ Commit message required")
    return 1
  }

  println("💾 Creating commit...")

  let repo = openRepo(".")
  let commitHash = createCommit(repo, message, author)

  println("✅ Commit created: " + substr(commitHash, 0, 8))
  return 0
}

fn cmdLog(maxCount: i32): i32 {
  println("📜 Commit History:")
  println("---")

  let repo = openRepo(".")
  let commits = showLog(repo, maxCount)

  for commit in commits {
    # TODO: 커밋 정보 포맷팅
  }

  return 0
}

fn cmdFsck(): i32 {
  println("🔍 Checking repository integrity...")

  let repo = openRepo(".")
  let result = fsck(repo)

  if result["isValid"] {
    println("✅ Repository is valid")
    return 0
  } else {
    println("❌ Repository has issues:")
    let corrupted = result["corruptedObjects"]
    for obj in corrupted {
      println("  - " + obj)
    }
    return 1
  }
}

fn cmdCatFile(hash: string): i32 {
  if hash == "" {
    println("❌ Hash required")
    return 1
  }

  let repo = openRepo(".")
  let obj = catFile(repo, hash)

  println("Object: " + hash)
  println("Type: " + obj["type"])
  println("Size: " + toString(obj["size"]))

  return 0
}

fn cmdStatus(): i32 {
  println("📊 Repository Status:")

  let repo = openRepo(".")
  let status = status(repo)
  let stats = status["statistics"]

  println("Total Objects: " + toString(stats["totalObjects"]))
  println("Total Size: " + toString(stats["totalSize"]) + " bytes")
  println("Index Dirty: " + toString(status["indexDirty"]))

  return 0
}

fn cmdHelp(): i32 {
  println("🚀 FreeGit - Git Implementation in FreeLang")
  println("")
  println("Usage: freegit <command> [options]")
  println("")
  println("Commands:")
  println("  init                Initialize a new repository")
  println("  add <files...>      Add files to staging area")
  println("  commit <msg>        Create a commit")
  println("  log [count]         Show commit history")
  println("  status              Show repository status")
  println("  fsck                Check repository integrity")
  println("  cat-file <hash>     Show object contents")
  println("  help                Show this help message")
  println("")

  return 0
}

# ================================================================
# Part 4: 저장소 접근
# ================================================================

fn openRepo(path: string): map {
  # TODO: {path}/.freegit 에서 저장소 정보 로드
  return initializeRepository(path)
}

# ================================================================
# Part 5: 유틸리티
# ================================================================

fn println(text: string): any {
  # TODO: 표준 출력
  return null
}

fn toString(value: any): string {
  # TODO: 값을 문자열로 변환
  return ""
}

fn parseInt(s: string): i32 {
  # TODO: 문자열을 정수로 파싱
  return 0
}

fn slice(arr: [string], start: i32, end: i32): [string] {
  let result = [] as [string]
  for i in range(start, end) {
    result = append(result, arr[i])
  }
  return result
}

# ================================================================
# Part 6: 메인 진입점
# ================================================================

fn main(args: [string]): i32 {
  let parsedCmd = parseCommand(args)
  return executeCommand(parsedCmd)
}

