# 단계 기록
fn recordStep(session: map, stepName: string, status: string, detail: string): map {
  let step = {
    "name": stepName,
    "status": status,     # "ok" | "skip" | "error"
    "detail": detail,
    "ts": getCurrentTimestamp()
  }
  session["steps"] = append(session["steps"], step)
  return session
}

# 사이클 완료 처리
fn finishCycle(session: map, finalStatus: string): map {
  session["finishedAt"] = getCurrentTimestamp()
  session["status"] = finalStatus
  return session
}

# 경과 시간 계산 (초)
fn elapsedSeconds(session: map): i32 {
  if session["finishedAt"] == 0 { return 0 }
  return session["finishedAt"] - session["startedAt"]
}

# ================================================================
# Part 2: Step 1 - GOGS 저장소 스냅샷
# ================================================================

fn stepFetchRepos(session: map): map {
  let snapshots = buildSampleGogsSnapshots()

  if len(snapshots) == 0 {
    session["errors"] = append(session["errors"], "GOGS: 저장소 0개")
    session = recordStep(session, "fetch-repos", "error", "저장소 없음")
    return session
  }

  session["repoTargets"] = snapshots
  session = recordStep(session, "fetch-repos", "ok",
    intToStr(len(snapshots)) + "개 저장소 스냅샷 수집")
  return session
}

# ================================================================
# Part 3: Step 2 - 우선순위 정렬 + Step 3 - 전략 수립
# ================================================================

fn stepBuildStrategy(session: map): map {
  if len(session["repoTargets"]) == 0 {
    session = recordStep(session, "build-strategy", "skip", "대상 저장소 없음")
    return session
  }

  let snapshots = session["repoTargets"]
  let priorityList = buildMarketingPriorityList(snapshots)

  # 상위 3개만 선택
  let topN = if len(priorityList) >= 3 then 3 else len(priorityList)
  let selected = [] as [map]
  let i = 0
  while i < topN {
    selected = append(selected, priorityList[i])
    i = i + 1
  }

  session["repoTargets"] = selected

  let names = ""
  let j = 0
  while j < len(selected) {
    if j > 0 { names = names + ", " }
    names = names + selected[j]["repoName"]
    j = j + 1
  }

  session = recordStep(session, "build-strategy", "ok",
    "TOP " + intToStr(topN) + " 선정: " + names)
  return session
}

# ================================================================
# Part 4: Step 4 - 콘텐츠 생성
# ================================================================

fn generateBlogContent(repoName: string, repoHealth: string, latestCommitMsg: string): map {
  let title = "FreeLang " + repoName + " - 최신 업데이트 소개"

  let intro = "이번 포스트에서는 " + repoName + " 저장소의 최신 변경 사항을 소개합니다."
  let body = intro + "\n\n" +
    "## 주요 변경사항\n\n" +
    "최근 커밋: " + latestCommitMsg + "\n\n" +
    "## 저장소 상태\n\n" +
    "현재 저장소 건강도: **" + repoHealth + "**\n\n" +
    "## 다음 단계\n\n" +
    "로드맵 및 기여 방법은 [GOGS 저장소](https://gogs.dclub.kr/kim/" + repoName + ")에서 확인하세요."

  return {
    "repoName": repoName,
    "title": title,
    "body": body,
    "bodyLength": len(body),
    "generatedAt": getCurrentTimestamp()
  }
}

fn stepGenerateContent(session: map): map {
  if len(session["repoTargets"]) == 0 {
    session = recordStep(session, "generate-content", "skip", "대상 없음")
    return session
  }

  let targets = session["repoTargets"]
  let snapshots = buildSampleGogsSnapshots()
  let generated = [] as [map]
  let i = 0

  while i < len(targets) {
    let target = targets[i]
    let repoName = target["repoName"]

    # 스냅샷에서 상세 정보 찾기
    let health = "good"
    let latestMsg = "최신 업데이트"
    let si = 0
    while si < len(snapshots) {
      if snapshots[si]["repo"]["name"] == repoName {
        health = snapshots[si]["health"]
        latestMsg = snapshots[si]["latestCommit"]["shortMessage"]
        break
      }
      si = si + 1
    }

    let content = generateBlogContent(repoName, health, latestMsg)
    generated = append(generated, content)
    i = i + 1
  }

  session["generatedContent"] = generated
  session = recordStep(session, "generate-content", "ok",
    intToStr(len(generated)) + "개 블로그 포스트 생성")
  return session
}

# ================================================================
# Part 5: Step 5+6 - 채널 포맷 변환 + 발행 큐 등록
# ================================================================

fn stepDistributeAndQueue(session: map): map {
  if len(session["generatedContent"]) == 0 {
    session = recordStep(session, "distribute-queue", "skip", "생성된 콘텐츠 없음")
    return session
  }

  let pool = initializeConnectorPool()
  let queued = [] as [map]
  let content = session["generatedContent"]
  let channels = ["twitter", "linkedin", "blog"] as [string]
  let i = 0

  while i < len(content) {
    let post = content[i]
    let tags = ["FreeLang", post["repoName"], "OpenSource"] as [string]
    let media = [] as [string]

    let ci = 0
    while ci < len(channels) {
      let ch = channels[ci]
      let connector = findConnector(pool, ch)

      let payload = createPostPayload(
        ch,
        if ch == "blog" then "blog" else if ch == "twitter" then "thread" else "article",
        post["title"],
        post["body"],
        tags, media,
        getCurrentTimestamp() + calculateDelay(connector) * 60
      )

      if payload["isValid"] == true {
        let qItem = createQueueItem(payload, connector, i + 1)
        queued = append(queued, qItem)
      }
      ci = ci + 1
    }
    i = i + 1
  }

  session["queuedPosts"] = queued
  session = recordStep(session, "distribute-queue", "ok",
    intToStr(len(queued)) + "개 포스트 큐 등록 (3채널 × " + intToStr(len(content)) + "개)")
  return session
}

# ================================================================
# Part 6: Step 7 - 대시보드 HTML 생성
# ================================================================

fn stepBuildDashboard(session: map): map {
  # Agent Status 패널
  let agentHtml = runAgentStatusPanel("html")
  let agentOk = len(agentHtml) > 100

  # Analytics 패널
  let analyticsJson = runAnalyticsDashboard("json")
  let analyticsOk = contains(analyticsJson, "channels")

  # GOGS 패널
  let gogsJson = runGogsClient("json")
  let gogsOk = contains(gogsJson, "snapshots")

  if agentOk && analyticsOk && gogsOk {
    session = recordStep(session, "build-dashboard", "ok",
      "Agent(" + intToStr(len(agentHtml)) + "bytes) + Analytics + GOGS 대시보드 생성")
  } else {
    session["errors"] = append(session["errors"], "대시보드 생성 일부 실패")
    session = recordStep(session, "build-dashboard", "error", "일부 패널 생성 실패")
  }

  return session
}

# ================================================================
# Part 7: Step 8 - Proof Score 측정
# ================================================================

fn stepMeasureProof(session: map): map {
  let queued = session["queuedPosts"]

  if len(queued) == 0 {
    session = recordStep(session, "measure-proof", "skip", "큐된 포스트 없음")
    return session
  }

  # 시뮬레이션: 발행된 포스트에 대한 초기 메트릭
  let scores = [] as [map]
  let channels = ["twitter", "linkedin", "blog"] as [string]
  let i = 0

  while i < len(channels) {
    let ch = channels[i]
    # 초기 baseline (발행 직후 추정)
    let baseViews = if ch == "twitter" then 45
      else if ch == "linkedin" then 23
      else 12
    let baseLikes = if ch == "twitter" then 3
      else if ch == "linkedin" then 2
      else 1
    let baseComments = if ch == "twitter" then 1 else 0

    let score = {
      "channel": ch,
      "views": baseViews,
      "likes": baseLikes,
      "comments": baseComments,
      "proofScore": calculateProofScore(baseViews, baseLikes, baseComments),
      "engagementRate": if baseViews > 0 then ((baseLikes + baseComments) * 100) / baseViews else 0,
      "measuredAt": getCurrentTimestamp()
    }
    scores = append(scores, score)
    i = i + 1
  }

  session["proofScores"] = scores

  let totalProof = 0
  let si = 0
  while si < len(scores) {
    totalProof = totalProof + scores[si]["proofScore"]
    si = si + 1
  }

  session = recordStep(session, "measure-proof", "ok",
    "총 Proof Score: " + intToStr(totalProof) + " (" + intToStr(len(channels)) + "채널)")
  return session
}

# ================================================================
# Part 8: Step 9 - 사이클 리포트
# ================================================================

fn buildCycleReport(session: map): string {
  let elapsed = elapsedSeconds(session)
  let stepCount = len(session["steps"])
  let errorCount = len(session["errors"])
  let okSteps = 0
  let i = 0
  while i < stepCount {
    if session["steps"][i]["status"] == "ok" {
      okSteps = okSteps + 1
    }
    i = i + 1
  }

  let statusIcon = if session["status"] == "complete" then "✅"
    else if session["status"] == "partial" then "⚠️"
    else "❌"

  let report = "================================================================\n"
  report = report + statusIcon + " Deploy Cycle Report\n"
  report = report + "================================================================\n"
  report = report + "Cycle ID  : " + session["id"] + "\n"
  report = report + "Triggered : " + session["triggeredBy"] + "\n"
  report = report + "Status    : " + session["status"] + "\n"
  report = report + "Elapsed   : " + intToStr(elapsed) + "s\n"
  report = report + "Steps     : " + intToStr(okSteps) + "/" + intToStr(stepCount) + " OK\n"
  report = report + "Errors    : " + intToStr(errorCount) + "\n"
  report = report + "----------------------------------------------------------------\n"

  report = report + "\n📋 Step 실행 내역:\n"
  let j = 0
  while j < stepCount {
    let step = session["steps"][j]
    let icon = if step["status"] == "ok" then "  ✅"
      else if step["status"] == "skip" then "  ⏭️"
      else "  ❌"
    report = report + icon + " [" + step["name"] + "] " + step["detail"] + "\n"
    j = j + 1
  }

  if len(session["queuedPosts"]) > 0 {
    report = report + "\n📤 발행 큐:\n"
    report = report + "  " + intToStr(len(session["queuedPosts"])) + "개 포스트 대기 중\n"
  }

  if len(session["proofScores"]) > 0 {
    report = report + "\n📊 초기 Proof Score:\n"
    let pi = 0
    while pi < len(session["proofScores"]) {
      let ps = session["proofScores"][pi]
      report = report + "  " + ps["channel"] + ": " + intToStr(ps["proofScore"]) + "pt"
        + " (조회:" + intToStr(ps["views"]) + " 좋아요:" + intToStr(ps["likes"]) + " 댓글:" + intToStr(ps["comments"]) + ")\n"
      pi = pi + 1
    }
  }

  if errorCount > 0 {
    report = report + "\n⚠️ 에러:\n"
    let ei = 0
    while ei < errorCount {
      report = report + "  - " + session["errors"][ei] + "\n"
      ei = ei + 1
    }
  }

  report = report + "\n================================================================\n"
  report = report + "🎯 기록이 증명이다\n"
  report = report + "================================================================\n"

  return report
}

# JSON 리포트
fn buildCycleReportJson(session: map): string {
  let elapsed = elapsedSeconds(session)
  let stepCount = len(session["steps"])
  let errorCount = len(session["errors"])
  let okSteps = 0
  let i = 0
  while i < stepCount {
    if session["steps"][i]["status"] == "ok" { okSteps = okSteps + 1 }
    i = i + 1
  }

  let totalProof = 0
  let pi = 0
  while pi < len(session["proofScores"]) {
    totalProof = totalProof + session["proofScores"][pi]["proofScore"]
    pi = pi + 1
  }

  return "{" +
    "\"cycleId\":\"" + session["id"] + "\"," +
    "\"triggeredBy\":\"" + session["triggeredBy"] + "\"," +
    "\"status\":\"" + session["status"] + "\"," +
    "\"elapsedSeconds\":" + intToStr(elapsed) + "," +
    "\"stepsOk\":" + intToStr(okSteps) + "," +
    "\"stepsTotal\":" + intToStr(stepCount) + "," +
    "\"errors\":" + intToStr(errorCount) + "," +
    "\"queuedPosts\":" + intToStr(len(session["queuedPosts"])) + "," +
    "\"totalProofScore\":" + intToStr(totalProof) + "," +
    "\"version\":\"deploy-v1\"" +
  "}"
}

# ================================================================
# Part 9: 메인 사이클 실행기
# ================================================================

fn runDeployCycle(cycleId: string, triggeredBy: string): map {
  let session = createCycleSession(cycleId, triggeredBy)

  # Step 1: GOGS 저장소 수집
  session = stepFetchRepos(session)

  # Step 2+3: 전략 수립
  session = stepBuildStrategy(session)

  # Step 4: 콘텐츠 생성
  session = stepGenerateContent(session)

  # Step 5+6: 배포 큐 등록
  session = stepDistributeAndQueue(session)

  # Step 7: 대시보드 빌드
  session = stepBuildDashboard(session)

  # Step 8: Proof Score
  session = stepMeasureProof(session)

  # 완료
  let errorCount = len(session["errors"])
  let finalStatus = if errorCount == 0 then "complete"
    else if errorCount < 2 then "partial"
    else "failed"

  session = finishCycle(session, finalStatus)
  return session
}

# ================================================================
# Part 10: 엔트리포인트
# ================================================================

fn runDeploy(outputFormat: string): string {
  let session = runDeployCycle("cycle-" + intToStr(getCurrentTimestamp()), "manual")

  if outputFormat == "report" {
    return buildCycleReport(session)
  } else if outputFormat == "json" {
    return buildCycleReportJson(session)
  } else if outputFormat == "status" {
    return session["status"]
  } else {
    return "error: use 'report', 'json', or 'status'"
  }
}

