fn testCreateCycleSession(): bool {
  let session = createCycleSession("cycle-001", "manual")
  assert(session["id"] == "cycle-001", "id")
  assert(session["triggeredBy"] == "manual", "triggeredBy")
  assert(session["status"] == "running", "초기 running")
  assert(len(session["steps"]) == 0, "초기 steps 비어있음")
  assert(len(session["errors"]) == 0, "초기 errors 비어있음")
  return true
}

fn testRecordStep(): bool {
  let session = createCycleSession("test", "manual")
  session = recordStep(session, "fetch-repos", "ok", "5개 저장소")
  assert(len(session["steps"]) == 1, "step 1개 추가됨")
  assert(session["steps"][0]["name"] == "fetch-repos", "step 이름")
  assert(session["steps"][0]["status"] == "ok", "step 상태")
  assert(session["steps"][0]["detail"] == "5개 저장소", "step 상세")
  return true
}

fn testFinishCycle(): bool {
  let session = createCycleSession("test", "cron")
  session = finishCycle(session, "complete")
  assert(session["status"] == "complete", "완료 상태")
  assert(session["finishedAt"] > 0, "완료 시간 기록")
  return true
}

fn testElapsedSeconds(): bool {
  let session = createCycleSession("test", "manual")
  session["startedAt"] = 1742130000
  session["finishedAt"] = 1742130045
  assert(elapsedSeconds(session) == 45, "45초 경과")
  return true
}

fn testElapsedSecondsNotFinished(): bool {
  let session = createCycleSession("test", "manual")
  assert(elapsedSeconds(session) == 0, "완료 전 0초")
  return true
}

fn testStepFetchRepos(): bool {
  let session = createCycleSession("test", "manual")
  session = stepFetchRepos(session)
  assert(len(session["repoTargets"]) > 0, "저장소 수집됨")
  assert(len(session["steps"]) == 1, "1개 step 기록")
  assert(session["steps"][0]["name"] == "fetch-repos", "step 이름")
  assert(session["steps"][0]["status"] == "ok", "성공")
  return true
}

fn testStepBuildStrategy(): bool {
  let session = createCycleSession("test", "manual")
  session = stepFetchRepos(session)
  session = stepBuildStrategy(session)

  assert(len(session["repoTargets"]) <= 3, "상위 3개 이하 선택")
  assert(len(session["steps"]) == 2, "2개 step 기록")
  assert(session["steps"][1]["name"] == "build-strategy", "전략 step")
  return true
}

fn testStrategyTopN(): bool {
  let session = createCycleSession("test", "manual")
  session = stepFetchRepos(session)
  session = stepBuildStrategy(session)
  # 저장소가 5개여도 최대 3개만 선택
  assert(len(session["repoTargets"]) == 3, "TOP 3 선택")
  return true
}

fn testStepGenerateContent(): bool {
  let session = createCycleSession("test", "manual")
  session = stepFetchRepos(session)
  session = stepBuildStrategy(session)
  session = stepGenerateContent(session)

  assert(len(session["generatedContent"]) > 0, "콘텐츠 생성됨")
  assert(len(session["generatedContent"]) == len(session["repoTargets"]), "타겟 수만큼 생성")
  assert(session["steps"][2]["status"] == "ok", "생성 성공")
  return true
}

fn testGeneratedContentStructure(): bool {
  let session = createCycleSession("test", "manual")
  session = stepFetchRepos(session)
  session = stepBuildStrategy(session)
  session = stepGenerateContent(session)

  let content = session["generatedContent"]
  assert(len(content) > 0, "콘텐츠 있음")
  let first = content[0]
  assert(contains(first["title"], "FreeLang"), "제목에 FreeLang")
  assert(len(first["body"]) > 50, "본문 50자 이상")
  assert(first["generatedAt"] > 0, "생성 시간")
  return true
}

fn testStepDistributeAndQueue(): bool {
  let session = createCycleSession("test", "manual")
  session = stepFetchRepos(session)
  session = stepBuildStrategy(session)
  session = stepGenerateContent(session)
  session = stepDistributeAndQueue(session)

  assert(len(session["queuedPosts"]) > 0, "큐 등록됨")
  # 3개 콘텐츠 × 3채널 = 9개 (유효한 것만)
  assert(len(session["queuedPosts"]) <= 9, "최대 9개 포스트")
  return true
}

fn testQueueItemsHaveChannels(): bool {
  let session = createCycleSession("test", "manual")
  session = stepFetchRepos(session)
  session = stepBuildStrategy(session)
  session = stepGenerateContent(session)
  session = stepDistributeAndQueue(session)

  let queued = session["queuedPosts"]
  let hasTwitter = false
  let hasLinkedin = false
  let hasBlog = false
  let i = 0
  while i < len(queued) {
    let ch = queued[i]["channel"]
    if ch == "twitter" { hasTwitter = true }
    else if ch == "linkedin" { hasLinkedin = true }
    else if ch == "blog" { hasBlog = true }
    i = i + 1
  }
  assert(hasTwitter, "Twitter 채널 포함")
  assert(hasLinkedin, "LinkedIn 채널 포함")
  assert(hasBlog, "Blog 채널 포함")
  return true
}

